// One row per scheduled export that is due. Row counts are the estimate the
// planner returns before the job is built, not a count(*).
const jobs = [
    {
        "id": "exp-9114",
        "account": "Lumen Labs",
        "dataset": "events",
        "rows": 52184
    },
    {
        "id": "exp-9115",
        "account": "Ember Commerce",
        "dataset": "events",
        "rows": 18402
    },
    {
        "id": "exp-9116",
        "account": "Lumen Labs",
        "dataset": "invoices",
        "rows": 1291
    },
    {
        "id": "exp-9117",
        "account": "Harbor Mobility",
        "dataset": "events",
        "rows": 74910
    },
    {
        "id": "exp-9118",
        "account": "Fieldnote Studio",
        "dataset": "attachments",
        "rows": 640
    }
];
node.status({ fill: 'blue', shape: 'dot', text: jobs.length + ' due' });
return [jobs.map(job => ({ payload: job, topic: job.id }))];

// Under the limit the job is streamed straight out and never touches a worker.
const job = msg.payload;
msg.payload = {
    ...job,
    route: 'streaming',
    object: `s3://northstar-exports/${job.account.toLowerCase().replace(/ /g, '-')}/${job.id}.csv.gz`,
    seconds: Math.round(job.rows / 9000),
    status: 'delivered',
};
node.status({ fill: 'green', shape: 'dot', text: job.id + ' delivered' });
return msg;

// Above the limit the planner falls back to the batch worker, which still
// carries the 120 second timeout the scheduler was supposed to have replaced.
// relay-core issue 318.
const job = msg.payload;
const seconds = Math.round(job.rows / 430);
msg.payload = {
    ...job,
    route: 'legacy-worker',
    timeoutSeconds: 120,
    estimatedSeconds: seconds,
    status: seconds > 120 ? 'timed out' : 'delivered',
};
node.status({
    fill: seconds > 120 ? 'red' : 'green',
    shape: 'dot',
    text: `${job.id} ${seconds}s`,
});
// First output is the run that ran out of time; second is the one that made it.
return seconds > 120 ? [msg, null] : [null, msg];

// What the support case Lumen opened on 18 August was raised from.
const job = msg.payload;
msg.payload = {
    case: 'scheduled export stops at two minutes',
    account: job.account,
    job: job.id,
    rows: job.rows,
    reachedSeconds: job.timeoutSeconds,
    neededSeconds: job.estimatedSeconds,
    tracked: 'relay-core#318',
    workaround: 'run the export in two halves by date range',
};
node.warn(`${job.account}: ${job.id} stopped at ${job.timeoutSeconds}s, needed ${job.estimatedSeconds}s`);
return msg;

// Every invoice worth looking at this morning, sorted into what should happen
// to it. Days are counted from today, so an invoice that was fine yesterday
// turns up in a different bucket on its own.
const today = new Date();
const invoices = [
    {
        "number": "4471",
        "account": "Lumen Labs",
        "amount": 412.0,
        "due": "2026-08-30",
        "status": "open"
    },
    {
        "number": "2607-63",
        "account": "Harbor Mobility",
        "amount": 356.0,
        "due": "2026-08-11",
        "status": "paid"
    },
    {
        "number": "2607-18",
        "account": "Fieldnote Studio",
        "amount": 99.0,
        "due": "2026-08-08",
        "status": "paid"
    },
    {
        "number": "2607-42",
        "account": "Ember Commerce",
        "amount": 289.0,
        "due": "2026-08-05",
        "status": "paid"
    }
];
node.status({ fill: 'blue', shape: 'dot', text: invoices.length + ' open' });
return [invoices.map(invoice => {
    const days = Math.round((new Date(invoice.due) - today) / 86400000);
    const bucket = invoice.status === 'paid' ? 'settled'
        : days < 0 ? 'overdue'
        : days <= 10 ? 'due-soon'
        : 'later';
    return { topic: invoice.number, payload: { ...invoice, daysToDue: days, bucket } };
})];

const invoice = msg.payload;
msg.payload = {
    ...msg.payload,
    action: 'send the reminder',
    to: 'accounts@' + invoice.account.toLowerCase().replace(/ /g, '') + '.droplive.test',
};
node.status({ fill: 'red', shape: 'dot', text: invoice.number + ' overdue' });
return msg;

// 4471 is held back on purpose. The account is mid-conversation about the
// export incident and the renewal review is next week; a reminder in the middle
// of that reads as a threat.
const invoice = msg.payload;
const held = invoice.number === '4471';
msg.payload = {
    ...invoice,
    action: held ? 'hold until the renewal review' : 'send the friendly notice',
    reason: held ? 'Lumen renewal in progress' : undefined,
};
node.status({
    fill: held ? 'yellow' : 'grey',
    shape: held ? 'ring' : 'dot',
    text: invoice.number + (held ? ' held' : ' notice'),
});
return msg;

node.status({ fill: 'grey', shape: 'ring', text: msg.payload.number + ' not due' });
msg.payload = { ...msg.payload, action: 'leave it' };
return msg;

node.status({ fill: 'green', shape: 'ring', text: msg.payload.number + ' settled' });
msg.payload = { ...msg.payload, action: 'nothing, it is paid' };
return msg;
